  ('rc4088-rev23', '9367', 'Total operating expenses', 'Operating expenses', true, false, 'This item represents the sum of all operating expense amounts.'),
  ('rc4088-rev23', '9368', 'Total expenses', 'Operating expenses', true, true, 'This item must be reported if there are no farming expenses (see “Validity check items” on page 7). Any amount reported under this item should be equal to the amount reported under item 8518 – Cost of sales, plus the amount reported under item 9367 – Total operating expenses.'),
  ('rc4088-rev23', '9369', 'Net non - farming income', 'Operating expenses', true, false, 'The amount reported should be equal to the amount reported under item 8299 – Total revenue, minus the amount reported under item 9368 – Total expenses. As a farming corporation or partnership, you may choose to report your income using the cash method rather than the accrual method. If you are involved in more than one business activity, only your farming business can use the cash method.'),
  ('rc4088-rev23', '9970', 'Net income/loss before taxes and extraordinary items', 'Extraordinary items and income taxes', true, false, 'This item represents the sum of item 9369 – Net non-farming income, and item 9899 – Net farm income. For partnerships, this item is called Net income/loss before extraordinary items .'),
  ('rc4088-rev23', '9975', 'Extraordinary item(s)', 'Extraordinary items and income taxes', true, false, 'This item includes gains/losses resulting from events that: are not expected to occur regularly over a period ■ of years do not typify normal business activities ■ do not depend primarily on decisions or ■ determinations by management Examples include the expropriation of a corporation’s or partnership’s land and buildings for a highway, the destruction of a large portion of a wheat crop by a tornado, and an explosion in a nuclear reactor resulting in high-level radioactive emission.'),
  ('rc4088-rev23', '9976', 'Legal settlements', 'Extraordinary items and income taxes', true, false, 'settlement of royalties'),
  ('rc4088-rev23', '9980', 'Unrealized gains/losses', 'Extraordinary items and income taxes', true, false, 'unrealized gains/losses resulting from the adjustment of book values on the revaluation of assets'),
  ('rc4088-rev23', '9985', 'Unusual items', 'Extraordinary items and income taxes', true, false, 'asset valuation adjustments such as write-downs and write-offs to net realizable values, items to be scrapped, and gains/losses from discontinued operations or wind-up of subsidiaries/affiliates. This item represents unusual and non-recurring items that do not meet the criteria set out for extraordinary gains/losses.'),
  ('rc4088-rev23', '9990', 'Current income taxes (corporations only)', 'Extraordinary items and income taxes', true, false, 'Canadian income taxes, federal income/large corporation tax, previous year adjustment to federal income/large corporation tax, and provincial and territorial income taxes'),
  ('rc4088-rev23', '9995', 'Future (deferred) income tax provision', 'Extraordinary items and income taxes', true, false, '(corporations only) Canadian income taxes deferred, provision for deferred income taxes, and provision for future income taxes'),
  ('rc4088-rev23', '9999', 'Net income/loss after taxes and extraordinary items', 'Extraordinary items and income taxes', true, true, 'For partnerships this item is called Net income/loss after extraordinary items. This item represents the net amount of the following items: Item 9970 – Net income/loss before taxes and extraordinary items Item 9975 – Extraordinary item(s) Item 9976 – Legal settlements Item 9980 – Unrealized gains/losses Item 9985 – Unusual items Item 9990 – Current income taxes Item 9995 – Future (deferred) income tax provision Item 9998 – Total of other comprehensive income Item 9999 must be reported (see “Validity check items” on page 7).');
