-- Closebook (Phase 3 batch, Nov 11, 2026), build step 1, part 1: the structure.
-- - A "Closebook" permission area. Owners have it; other roles start at None until an owner grants it
--   on Team and roles (year-end files hold client financials).
-- - Reference data from the batch appendices, generated by scripts/gen-closebook-seed.ts:
--   GIFI codes (Appendix A, versioned), tax codes, lead sheets and the 419 master lines (Appendix B).
--   Today's year-end package captions sit on the master lines' statement line (batch section 6).
-- - Closebook settings: thresholds and the Note 1 accounting policy.
-- Readable by anyone with Closebook; only owners change it, through the functions below, and every
-- change to a master line is logged with its reason (batch 4.1).

alter table public.role_permissions disable trigger role_permissions_guard_owner;
select r.id, 'closebook', case when r.is_owner then 'edit' else 'none' end from public.roles r
on conflict (role_id, area_key) do nothing;
alter table public.role_permissions enable trigger role_permissions_guard_owner;

create table public.cb_gifi_versions (
  id         text primary key,
  label      text not null,
  source     text not null default '',
  is_current boolean not null default false,
  loaded_at  timestamptz not null default now()
);
create unique index cb_gifi_versions_one_current on public.cb_gifi_versions (is_current) where is_current;

create table public.cb_gifi_codes (
  version_id  text not null references public.cb_gifi_versions (id),
  code        text not null check (code ~ '^\d{4}$'),
  name        text not null,
  section     text not null,
  generic     boolean not null default false,
  required    boolean not null default false,
  description text not null default '',
  primary key (version_id, code)
);

create table public.cb_tax_codes (
  code             text primary key check (code ~ '^[A-Z0-9]{2,10}$'),
  name             text not null,
  schedule1_effect text not null default '',
  used_for         text not null default '',
  sort_order       int not null
);

create table public.cb_lead_sheets (
  code       text primary key check (code ~ '^([A-H]|[A-H]{2}|\d{2})$'),
  name       text not null,
  sort_order int not null
);

create table public.cb_master_lines (
  line_no          text primary key check (line_no ~ '^\d{4}\.\d{2}$'),
  name             text not null check (length(btrim(name)) between 1 and 200),
  gifi_code        text not null check (gifi_code ~ '^\d{4}$' and line_no like gifi_code || '.%'),
  gifi_name        text not null,
  section          text not null,
  line_type        text not null check (line_type in ('Asset', 'Liability', 'Equity', 'Revenue', 'Expense')),
  lead_sheet       text references public.cb_lead_sheets (code),
  statement_line   text,
  default_tax_code text references public.cb_tax_codes (code),
  mappable         boolean not null,
  pair_line        text, -- the line an opposite balance moves to (checked once the lines are loaded, below)
  required_gifi    boolean not null default false,
  note             text not null default '',
  sort_order       numeric not null,
  updated_at       timestamptz not null default now(),
  updated_by       uuid references public.staff (id),
  -- Every line staff can map to has its lead sheet, statement line and tax code; total lines have none.
  check (not mappable or (lead_sheet is not null and statement_line is not null and default_tax_code is not null))
);

-- Every change to a master line, with its reason (owners only).
create table public.cb_master_line_log (
  id         bigint generated always as identity primary key,
  line_no    text not null references public.cb_master_lines (line_no),
  action     text not null check (action in ('edit', 'add')),
  changes    jsonb not null,
  reason     text not null check (length(btrim(reason)) between 3 and 500),
  changed_by uuid references public.staff (id),
  changed_at timestamptz not null default now()
);

-- One row: thresholds (batch section 7) and the Note 1 accounting policy (batch 5.6).
create table public.cb_settings (
  id                     boolean primary key default true check (id),
  recon_outstanding_max  numeric(12, 2) not null default 5000 check (recon_outstanding_max >= 0),
  flag_amount            numeric(12, 2) not null default 5000 check (flag_amount >= 0),
  flag_percent           numeric(5, 2)  not null default 20 check (flag_percent between 0 and 1000),
  entry_review_amount    numeric(12, 2) not null default 5000 check (entry_review_amount >= 0),
  capital_invoice_amount numeric(12, 2) not null default 5000 check (capital_invoice_amount >= 0),
  note1_policy           text not null default 'amortization_equals_cca' check (note1_policy in ('amortization_equals_cca')),
  updated_at             timestamptz not null default now(),
  updated_by             uuid references public.staff (id)
);

-- BEGIN GENERATED (scripts/gen-closebook-seed.ts from docs/phase3 Appendices A and B)




-- END GENERATED

alter table public.cb_master_lines add constraint cb_master_lines_pair_line_fkey foreign key (pair_line) references public.cb_master_lines (line_no);

-- Security: read with Closebook; no direct writes (owners use the functions below).
alter table public.cb_gifi_versions enable row level security;
alter table public.cb_gifi_versions force row level security;
alter table public.cb_gifi_codes enable row level security;
alter table public.cb_gifi_codes force row level security;
alter table public.cb_tax_codes enable row level security;
alter table public.cb_tax_codes force row level security;
alter table public.cb_lead_sheets enable row level security;
alter table public.cb_lead_sheets force row level security;
alter table public.cb_master_lines enable row level security;
alter table public.cb_master_lines force row level security;
alter table public.cb_master_line_log enable row level security;
alter table public.cb_master_line_log force row level security;
alter table public.cb_settings enable row level security;
alter table public.cb_settings force row level security;
create policy "Closebook viewers read GIFI versions" on public.cb_gifi_versions for select to authenticated using ((select private.can_view('closebook')));
create policy "Closebook viewers read GIFI codes" on public.cb_gifi_codes for select to authenticated using ((select private.can_view('closebook')));
create policy "Closebook viewers read tax codes" on public.cb_tax_codes for select to authenticated using ((select private.can_view('closebook')));
create policy "Closebook viewers read lead sheets" on public.cb_lead_sheets for select to authenticated using ((select private.can_view('closebook')));
create policy "Closebook viewers read master lines" on public.cb_master_lines for select to authenticated using ((select private.can_view('closebook')));
create policy "Owners read the master line log" on public.cb_master_line_log for select to authenticated using ((select private.is_owner()));
create policy "Closebook viewers read Closebook settings" on public.cb_settings for select to authenticated using ((select private.can_view('closebook')));
grant select on public.cb_gifi_versions, public.cb_gifi_codes, public.cb_tax_codes, public.cb_lead_sheets,
  public.cb_master_lines, public.cb_master_line_log, public.cb_settings to authenticated;

-- Owner changes show in the activity log too.
create trigger cb_master_lines_log after insert or update or delete on public.cb_master_lines
  for each row execute function private.log_change();
create trigger cb_settings_log after update on public.cb_settings
  for each row execute function private.log_change();

-- Owners: change a master line's name, statement line, default tax code, lead sheet or note, with a
-- reason. GIFI code, section and type stay as CRA defines them. Total lines: name and note only.
create or replace function public.cb_update_master_line(p_line text, p_name text, p_statement_line text, p_tax_code text, p_lead_sheet text, p_note text, p_reason text)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v public.cb_master_lines;
  v_changes jsonb := '{}';
begin
  perform private.require(private.is_owner(), 'Only an owner can change GIFI lines.');
  perform private.require(length(btrim(coalesce(p_reason, ''))) >= 3, 'Give a reason for the change.');
  select * into v from public.cb_master_lines where line_no = p_line for update;
  perform private.require(v.line_no is not null, 'Line not found.');
  if not v.mappable then
    perform private.require(p_statement_line is not distinct from v.statement_line and p_tax_code is not distinct from v.default_tax_code
      and p_lead_sheet is not distinct from v.lead_sheet, 'A total line is calculated: only its name and note can change.');
  end if;
  if btrim(p_name) is distinct from v.name then v_changes := v_changes || jsonb_build_object('name', jsonb_build_array(v.name, btrim(p_name))); end if;
  if nullif(btrim(p_statement_line), '') is distinct from v.statement_line then v_changes := v_changes || jsonb_build_object('statement_line', jsonb_build_array(v.statement_line, nullif(btrim(p_statement_line), ''))); end if;
  if p_tax_code is distinct from v.default_tax_code then v_changes := v_changes || jsonb_build_object('default_tax_code', jsonb_build_array(v.default_tax_code, p_tax_code)); end if;
  if p_lead_sheet is distinct from v.lead_sheet then v_changes := v_changes || jsonb_build_object('lead_sheet', jsonb_build_array(v.lead_sheet, p_lead_sheet)); end if;
  if btrim(coalesce(p_note, '')) is distinct from v.note then v_changes := v_changes || jsonb_build_object('note', jsonb_build_array(v.note, btrim(coalesce(p_note, '')))); end if;
  perform private.require(v_changes <> '{}', 'Nothing changed.');
  update public.cb_master_lines
     set name = btrim(p_name), statement_line = nullif(btrim(p_statement_line), ''), default_tax_code = p_tax_code,
         lead_sheet = p_lead_sheet, note = btrim(coalesce(p_note, '')), updated_at = now(), updated_by = (select auth.uid())
   where line_no = p_line;
end;
$$;

-- Owners: add a sub-line under a mappable line (same GIFI code, its own name and treatment), with a
-- reason. Numbered .10, .20 ... after the highest sub-line of that GIFI code.
create or replace function public.cb_add_sub_line(p_parent text, p_name text, p_statement_line text, p_tax_code text, p_note text, p_reason text)
returns text language plpgsql security definer set search_path = '' as $$
declare
  v public.cb_master_lines;
  v_next int;
  v_line text;
begin
  perform private.require(private.is_owner(), 'Only an owner can add GIFI lines.');
  perform private.require(length(btrim(coalesce(p_reason, ''))) >= 3, 'Give a reason for the new line.');
  perform private.require(length(btrim(coalesce(p_name, ''))) >= 2, 'Give the new line a name.');
  select * into v from public.cb_master_lines where line_no = p_parent;
  perform private.require(v.line_no is not null and v.mappable, 'Choose a line staff can map to.');
  select coalesce(max(split_part(line_no, '.', 2)::int), 0) + 10 into v_next from public.cb_master_lines where gifi_code = v.gifi_code;
  perform private.require(v_next <= 90, 'This GIFI code already has nine sub-lines.');
  v_line := v.gifi_code || '.' || lpad(v_next::text, 2, '0');
  values (v_line, btrim(p_name), v.gifi_code, v.gifi_name, v.section, v.line_type, v.lead_sheet,
          coalesce(nullif(btrim(p_statement_line), ''), v.statement_line), coalesce(p_tax_code, v.default_tax_code), true, v.pair_line, false,
          btrim(coalesce(p_note, '')), v.sort_order + v_next / 1000.0, (select auth.uid()));
  values (v_line, 'add', jsonb_build_object('from', p_parent, 'name', btrim(p_name)), btrim(p_reason), (select auth.uid()));
  return v_line;
end;
$$;

-- Owners: thresholds and the Note 1 policy.
create or replace function public.cb_update_settings(p_recon numeric, p_flag_amount numeric, p_flag_percent numeric, p_entry_review numeric, p_capital_invoice numeric, p_note1 text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform private.require(private.is_owner(), 'Only an owner can change Closebook settings.');
  update public.cb_settings
     set recon_outstanding_max = p_recon, flag_amount = p_flag_amount, flag_percent = p_flag_percent,
         entry_review_amount = p_entry_review, capital_invoice_amount = p_capital_invoice, note1_policy = p_note1,
         updated_at = now(), updated_by = (select auth.uid())
   where id;
end;
$$;

revoke all on function public.cb_update_master_line(text, text, text, text, text, text, text), public.cb_add_sub_line(text, text, text, text, text, text),
  public.cb_update_settings(numeric, numeric, numeric, numeric, numeric, text) from public, anon;
grant execute on function public.cb_update_master_line(text, text, text, text, text, text, text), public.cb_add_sub_line(text, text, text, text, text, text),
  public.cb_update_settings(numeric, numeric, numeric, numeric, numeric, text) to authenticated;
